const item = $input.item.json;
const text = (item.messageText || '').toLowerCase();

const keywordCategories = {
  urgency: ['act now', 'immediately', 'urgent', 'right away', 'expires today', 'act fast', 'final notice', 'do not delay'],
  paymentMethod: ['gift card', 'gift cards', 'wire transfer', 'bitcoin', 'cryptocurrency', 'prepaid card', 'money order', 'itunes card', 'google play card', 'read me the codes', 'read the codes'],
  secrecy: ["don't tell", 'do not tell', 'keep this between us', 'confidential', 'secret', 'do not discuss this with anyone', 'tell no one'],
  threats: ['arrest', 'arrested', 'lawsuit', 'jail', 'warrant', 'suspend your', 'legal action', 'frozen your account', 'seize your assets'],
  impersonatedAuthority: ['social security', 'irs', 'medicare', 'the bank', 'your bank', 'amazon', 'tech support', 'microsoft', 'grandson', 'granddaughter', 'grandchild', 'government agency']
};

const categoryWeights = {
  urgency: 12,
  paymentMethod: 25,
  secrecy: 20,
  threats: 20,
  impersonatedAuthority: 8
};

const matchedFlags = [];
let heuristicScore = 0;

for (const [category, keywords] of Object.entries(keywordCategories)) {
  let categoryMatched = false;
  for (const kw of keywords) {
    if (text.includes(kw)) {
      matchedFlags.push(category + ': "' + kw + '"');
      categoryMatched = true;
    }
  }
  if (categoryMatched) heuristicScore += categoryWeights[category];
}

heuristicScore = Math.max(0, Math.min(100, heuristicScore));

return {
  json: {
    ...item,
    heuristicFlags: matchedFlags,
    heuristicScore,
    heuristicFlagCount: matchedFlags.length
  }
};

const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
  if (typeof parsed.analysisConfidence !== 'number') throw new Error('missing confidence');
} catch (e) {
  const fallbackRisk = (item.heuristicScore || 0) >= 50 ? 65 : 45;
  parsed = {
    analysisConfidence: 3,
    isLikelyScam: true,
    scamType: 'Unclear - AI parsing failed, treat as a placeholder',
    aiRiskScore: fallbackRisk,
    redFlagsDetected: ['AI analysis parsing failed - flagged for manual review as a precaution'],
    whyThisIsRisky: 'We could not fully analyze this message automatically, so it is being treated cautiously until a person reviews it.',
    requiresUrgentFamilyAlert: (item.heuristicScore || 0) >= 50
  };
}

return {
  json: {
    ...item,
    analysisConfidence: parsed.analysisConfidence,
    isLikelyScam: parsed.isLikelyScam,
    scamType: parsed.scamType,
    aiRiskScore: parsed.aiRiskScore,
    redFlagsDetected: parsed.redFlagsDetected,
    whyThisIsRisky: parsed.whyThisIsRisky,
    requiresUrgentFamilyAlert: parsed.requiresUrgentFamilyAlert
  }
};

const item = $input.item.json;
const heuristicScore = item.heuristicScore || 0;
const aiRiskScore = item.aiRiskScore || 0;
const redFlagCount = (item.redFlagsDetected || []).length;

// Weighted blend of the independent keyword heuristic and the AI's own assessment,
// with a small boost for the number of distinct red flags the AI actually named.
let compositeRiskScore = Math.round(
  (heuristicScore * 0.4) +
  (aiRiskScore * 0.6) +
  Math.min(redFlagCount * 2, 10)
);
compositeRiskScore = Math.max(0, Math.min(100, compositeRiskScore));

let riskTier = 'Low Risk';
if (compositeRiskScore >= 80) riskTier = 'Critical Risk';
else if (compositeRiskScore >= 55) riskTier = 'High Risk';
else if (compositeRiskScore >= 30) riskTier = 'Medium Risk';

const requiresFamilyAlert = riskTier === 'High Risk' || riskTier === 'Critical Risk' || item.requiresUrgentFamilyAlert === true;

return {
  json: {
    ...item,
    compositeRiskScore,
    riskTier,
    requiresFamilyAlert
  }
};

const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    overallSafetyRecommendation: 'Do Not Engage - Block and Report',
    plainLanguageExplanation: 'We could not fully process this automatically, so please treat this message with caution. Do not send any money or share personal information. Talk to a family member or call the organization directly using a number you look up yourself, not one given in the message.',
    stepByStepActions: ['Do not respond, click links, or send any money.', 'Do not give out personal or account information.', 'Talk to a trusted family member before taking any action.'],
    whatToSayIfContactedAgain: 'I need to verify this independently before doing anything. I will call you back using a number I look up myself.',
    familyAlertMessage: 'A message reached ' + (item.recipientName || 'a family member') + ' that could not be automatically verified as safe. Please review it together as a precaution.',
    recommendationConfidence: 40
  };
}

const decidedAt = new Date().toISOString();

return {
  json: {
    ...item,
    ...parsed,
    decidedAt,
    reportSummaryRow: [
      item.reportId || 'N/A',
      item.recipientName || '',
      item.messageChannel || '',
      item.claimedIdentity || '',
      item.compositeRiskScore || 0,
      item.riskTier || '',
      item.isLikelyScam || false,
      item.scamType || '',
      parsed.overallSafetyRecommendation || '',
      item.requiresFamilyAlert || false,
      decidedAt
    ]
  }
};

